@Entity
class Order {
    @Id @GeneratedValue
    Long id;
    @OneToMany(mappedBy = "order")
    List<Item> items;
}

class UserService {
    // one instance, shared by every request thread
    private final EntityManager em;

    User load(long id) {
        return em.find(User.class, id);
    }
}

User a = em.find(User.class, 10L);
User b = em.find(User.class, 10L);
System.out.println(a == b);

@Transactional
void rename(long id) {
    User u = em.find(User.class, id);
    u.setEmail("new@mail.com");
}

Order order = em.find(Order.class, 1L);   // items is LAZY
System.out.println("order loaded");
int count = order.getItems().size();

